import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 inp_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Hin,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 Hout,
    .param .u32 Wout
)
{
    .reg .pred %p_exit, %p;
    .reg .b32 %r_tid, %r_tmp0, %r_tmp1, %r_cta;
    .reg .b32 %r_total, %rN, %rCin, %rHin, %rWin, %rCout, %rKH, %rKW, %rSh, %rSw, %rPh, %rPw, %rHout, %rWout;
    .reg .b32 %r_rem0, %r_rem1, %r_rem2, %r_wo, %r_ho, %r_co, %r_n;
    .reg .b32 %r_t0, %r_t1, %r_t2, %r_t3, %r_t4, %r_t5;
    .reg .b32 %r_wbase_s32, %r_hbase_s32, %r_hin_s32, %r_win_s32;
    .reg .b32 %r_c, %r_kh, %r_kw;
    .reg .b32 %r_idx_nc, %r_idx_nch, %r_in_base, %r_win_u32;
    .reg .b32 %r_w_cc, %r_w_cch, %r_w_base_idx;
    .reg .b64 %rd_inp, %rd_w, %rd_b, %rd_out, %addr_inp, %addr_w, %addr_out, %ofs_bytes, %addr_bias;
    .reg .f32 %f_acc, %f_in, %f_w, %f_bias;

    // Load parameters
    ld.param.u64 %rd_inp, [inp_ptr];
    ld.param.u64 %rd_w,   [w_ptr];
    ld.param.u64 %rd_b,   [b_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.u32 %rN,     [N];
    ld.param.u32 %rCin,   [Cin];
    ld.param.u32 %rHin,   [Hin];
    ld.param.u32 %rWin,   [Win];
    ld.param.u32 %rCout,  [Cout];
    ld.param.u32 %rKH,    [KH];
    ld.param.u32 %rKW,    [KW];
    ld.param.u32 %rSh,    [stride_h];
    ld.param.u32 %rSw,    [stride_w];
    ld.param.u32 %rPh,    [pad_h];
    ld.param.u32 %rPw,    [pad_w];
    ld.param.u32 %rHout,  [Hout];
    ld.param.u32 %rWout,  [Wout];

    // Compute global linear thread id
    mov.u32 %r_tmp0, %tid.x;
    mov.u32 %r_tmp1, %ntid.x;
    mov.u32 %r_cta,  %ctaid.x;
    mad.lo.u32 %r_tid, %r_cta, %r_tmp1, %r_tmp0;

    // total = N * Cout * Hout * Wout
    mul.lo.u32 %r_t0, %rN, %rCout;
    mul.lo.u32 %r_t1, %rHout, %rWout;
    mul.lo.u32 %r_total, %r_t0, %r_t1;

    setp.ge.u32 %p_exit, %r_tid, %r_total;
    @%p_exit bra DONE;

    // Decompose tid into (n, co, ho, wo) for NCHW layout with Cout as second dim
    mov.u32 %r_rem0, %r_tid;

    rem.u32 %r_wo, %r_rem0, %rWout;
    div.u32 %r_rem1, %r_rem0, %rWout;

    rem.u32 %r_ho, %r_rem1, %rHout;
    div.u32 %r_rem2, %r_rem1, %rHout;

    rem.u32 %r_co, %r_rem2, %rCout;
    div.u32 %r_n,  %r_rem2, %rCout;

    // acc = bias[co]
    mul.wide.u32 %ofs_bytes, %r_co, 4;
    add.s64 %addr_bias, %rd_b, %ofs_bytes;
    ld.global.f32 %f_bias, [%addr_bias];
    mov.f32 %f_acc, %f_bias;

    // wbase = (int)wo * stride_w - (int)pad_w
    mul.lo.u32 %r_t0, %r_wo, %rSw;
    cvt.s32.u32 %r_t1, %r_t0;
    cvt.s32.u32 %r_t2, %rPw;
    sub.s32 %r_wbase_s32, %r_t1, %r_t2;

    // hbase = (int)ho * stride_h - (int)pad_h
    mul.lo.u32 %r_t0, %r_ho, %rSh;
    cvt.s32.u32 %r_t1, %r_t0;
    cvt.s32.u32 %r_t2, %rPh;
    sub.s32 %r_hbase_s32, %r_t1, %r_t2;

    // Loop over input channels c
    mov.u32 %r_c, 0;
L_c_loop:
    setp.ge.u32 %p, %r_c, %rCin;
    @%p bra L_end_c;

    // (co*Cin + c)
    mul.lo.u32 %r_w_cc, %r_co, %rCin;
    add.u32 %r_w_cc, %r_w_cc, %r_c;

    // idx_nc = n*Cin + c
    mul.lo.u32 %r_idx_nc, %r_n, %rCin;
    add.u32 %r_idx_nc, %r_idx_nc, %r_c;

    // Loop over kernel height kh
    mov.u32 %r_kh, 0;
L_kh_loop:
    setp.ge.u32 %p, %r_kh, %rKH;
    @%p bra L_end_kh;

    // h_in = hbase + kh
    cvt.s32.u32 %r_t0, %r_kh;
    add.s32 %r_hin_s32, %r_hbase_s32, %r_t0;

    // if (h_in < 0 || h_in >= Hin) skip inner loop
    setp.lt.s32 %p, %r_hin_s32, 0;
    @%p bra L_skip_h;
    cvt.s32.u32 %r_t1, %rHin;
    setp.ge.s32 %p, %r_hin_s32, %r_t1;
    @%p bra L_skip_h;

    // in_base = ((idx_nc * Hin) + (u32)h_in) * Win
    mul.lo.u32 %r_idx_nch, %r_idx_nc, %rHin;
    cvt.u32.s32 %r_t2, %r_hin_s32;
    add.u32 %r_idx_nch, %r_idx_nch, %r_t2;
    mul.lo.u32 %r_in_base, %r_idx_nch, %rWin;

    // w_base_idx = (((co*Cin + c) * KH) + kh) * KW
    mul.lo.u32 %r_w_cch, %r_w_cc, %rKH;
    add.u32 %r_w_cch, %r_w_cch, %r_kh;
    mul.lo.u32 %r_w_base_idx, %r_w_cch, %rKW;

    // Loop over kernel width kw
    mov.u32 %r_kw, 0;
L_kw_loop:
    setp.ge.u32 %p, %r_kw, %rKW;
    @%p bra L_end_kw;

    // w_in = wbase + kw
    cvt.s32.u32 %r_t3, %r_kw;
    add.s32 %r_win_s32, %r_wbase_s32, %r_t3;

    // bounds check for w_in
    setp.lt.s32 %p, %r_win_s32, 0;
    @%p bra L_next_kw;
    cvt.s32.u32 %r_t4, %rWin;
    setp.ge.s32 %p, %r_win_s32, %r_t4;
    @%p bra L_next_kw;

    // Compute input index and load
    cvt.u32.s32 %r_win_u32, %r_win_s32;
    add.u32 %r_t5, %r_in_base, %r_win_u32;
    mul.wide.u32 %ofs_bytes, %r_t5, 4;
    add.s64 %addr_inp, %rd_inp, %ofs_bytes;

    // Compute weight index and load
    add.u32 %r_t0, %r_w_base_idx, %r_kw;
    mul.wide.u32 %ofs_bytes, %r_t0, 4;
    add.s64 %addr_w, %rd_w, %ofs_bytes;

    ld.global.f32 %f_in, [%addr_inp];
    ld.global.f32 %f_w,  [%addr_w];
    fma.rn.f32 %f_acc, %f_in, %f_w, %f_acc;

L_next_kw:
    add.u32 %r_kw, %r_kw, 1;
    bra L_kw_loop;

L_end_kw:
L_skip_h:
    add.u32 %r_kh, %r_kh, 1;
    bra L_kh_loop;

L_end_kh:
    add.u32 %r_c, %r_c, 1;
    bra L_c_loop;

L_end_c:
    // Store result to output: ((((n*Cout)+co)*Hout + ho)*Wout + wo)
    mul.lo.u32 %r_t0, %r_n, %rCout;
    add.u32 %r_t0, %r_t0, %r_co;
    mul.lo.u32 %r_t0, %r_t0, %rHout;
    add.u32 %r_t0, %r_t0, %r_ho;
    mul.lo.u32 %r_t0, %r_t0, %rWout;
    add.u32 %r_t0, %r_t0, %r_wo;

    mul.wide.u32 %ofs_bytes, %r_t0, 4;
    add.s64 %addr_out, %rd_out, %ofs_bytes;
    st.global.f32 [%addr_out], %f_acc;

DONE:
    ret;
}
"""

